const notes = new Map();
let counter = 0;

function nextId() {
  counter += 1;
  return `n${counter}`;
}

function isNonEmptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

export async function listTools() {
  return [
    {
      name: 'note_create',
      description: 'Create a note with a title and body. Returns the created note id.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'Title of the note.' },
          body: { type: 'string', description: 'Body content of the note.' },
        },
        required: ['title', 'body'],
        additionalProperties: false,
      },
    },
    {
      name: 'note_get',
      description: 'Retrieve a stored note by its id.',
      inputSchema: {
        type: 'object',
        properties: {
          note_id: { type: 'string', description: 'Id of the note to retrieve.' },
        },
        required: ['note_id'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name === 'note_create') {
    const { title, body } = args || {};
    if (!isNonEmptyString(title)) {
      throw new Error('title is required and must be a non-empty string');
    }
    if (!isNonEmptyString(body)) {
      throw new Error('body is required and must be a non-empty string');
    }
    const id = nextId();
    notes.set(id, { id, title, body });
    return {
      content: [{ type: 'text', text: `Created note ${id}: ${title}` }],
    };
  }

  if (name === 'note_get') {
    const { note_id } = args || {};
    if (!isNonEmptyString(note_id)) {
      throw new Error('note_id is required and must be a non-empty string');
    }
    const note = notes.get(note_id);
    if (!note) {
      throw new Error(`note not found: ${note_id}`);
    }
    return {
      content: [
        { type: 'text', text: `${note.title}\n\n${note.body}` },
      ],
    };
  }

  throw new Error(`unknown tool: ${name}`);
}
