{"command": "node -e "
import {listTools, callTool} from './server.mjs';
const assert = (c,m)=>{if(!c)throw new Error(m)};
// unknown tool
try{await callTool('nope',{});assert(false,'should throw unknown')}catch(e){assert(/unknown tool/.test(e.message),e.message)}
// empty title
try{await callTool('note_create',{title:'',body:'B'});assert(false,'should throw empty title')}catch(e){assert(/title/.test(e.message),e.message)}
// missing body
try{await callTool('note_create',{title:'A'});assert(false,'should throw missing body')}catch(e){assert(/body/.test(e.message),e.message)}
// empty note_id
try{await callTool('note_get',{note_id:''});assert(false,'should throw empty id')}catch(e){assert(/note_id/.test(e.message),e.message)}
// get unknown note
try{await callTool('note_get',{note_id:'n9999'});assert(false,'should throw not found')}catch(e){assert(/not found/.test(e.message),e.message)}
// stable ids
const a=await callTool('note_create',{title:'T1',body:'B1'});
const b=await callTool('note_create',{title:'T2',body:'B2'});
const aId=a.content[0].text.match(/n\d+/)[0];
const bId=b.content[0].text.match(/n\d+/)[0];
assert(aId==='n3'&&bId==='n4','ids should be stable/sequential, got '+aId+','+bId);
// get returns structured text content
const g=await callTool('note_get',{note_id:aId});
assert(Array.isArray(g.content)&&g.content[0].type==='text','structured text content');
assert(g.content[0].text.includes('T1'),'title present');
// listTools shape
const tools=await listTools();
assert(tools.length===2&&tools[0].name==='note_create'&&tools[1].name==='note_get','two tools');
assert(tools[0].inputSchema.required.includes('title')&&tools[0].inputSchema.required.includes('body'),'create required fields');
assert(tools[1].inputSchema.required.includes('note_id'),'get required field');
console.log('ALL EDGE CASES PASS');
"
"}

